          include: ['**/*'],
          exclude: DEFAULT_NATIVE_SNAPSHOT_CONFIG.exclude,
          max_files: 10_000,
          max_total_bytes: 1024 * 1024 * 1024,
          max_duration_ms: 60_000,
          max_selection_records: 20_000,
        },
      },
    });
